import { Offering } from './offeringPackage.entity.js';
import { InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { OfferingType } from './OfferingType.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { aggregationMethod, overageAllowedEnum } from '../../dimensions/dto/create-dimension.dto.js';

const dim = (over: any) => ({
    dimensionName: `name-${over.dimensionId}`,
    usageIncrement: '1',
    rounding: 'round',
    aggregationMethod: aggregationMethod.sum,
    consumptionUnit: { unit: 'count-based', type: 'count' },
    ...over,
});

const run = async (dimensions, usage, freeDimensionOnInvoice) => {
    const offeringConfig: any = {
        offeringId: 'off',
        offeringName: 'Plan',
        offeringType: OfferingType.subscription,
        billingCycle: ValidBillingCycles.monthly,
        dimensions,
        subscriptionPrice: 0,
    };
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate: new Date('2026-07-01T00:00:00Z'),
        endDate: new Date('2026-08-01T00:00:00Z'),
        lineItems,
        negative: false,
        businessID: 'biz',
        customerId: 'cus',
        customerService: undefined,
        dimensions,
        offeringInstance: Offering.getInstance(
            offeringConfig,
            'cus',
            'biz',
            undefined,
            { freeDimensionOnInvoice } as any,
            undefined,
            undefined,
            undefined,
            usage,
        ),
    });
    return lineItems.getLineItems();
};

describe('allowance and free dimension rules', () => {
    const usage = (dimensionId, value) => ({
        offeringId: 'off',
        dimensionId,
        usage: [{ value: String(value), startTime: '2026-07-02T00:00:00Z', endTime: '2026-07-02T00:00:00Z' }],
    });

    test('chargeableTotal rules', () => {
        expect(Offering.chargeableTotal({ total: 100 })).toBe(100);
        expect(Offering.chargeableTotal({ total: 100, usageEntitlement: 'inf', overageAllowed: overageAllowedEnum.true })).toBe(0);
        expect(Offering.chargeableTotal({ total: 100, usageEntitlement: 40, overageAllowed: overageAllowedEnum.true })).toBe(60);
        expect(Offering.chargeableTotal({ total: 100, usageEntitlement: 400, overageAllowed: overageAllowedEnum.true })).toBe(0);
        expect(Offering.chargeableTotal({ total: 100, usageEntitlement: 40, overageAllowed: overageAllowedEnum.false })).toBe(0);
        expect(Offering.chargeableTotal({ total: 100, usageEntitlement: 40 })).toBe(0);
        expect(Offering.chargeableTotal({ total: 100, usageEntitlement: 100, overageAllowed: overageAllowedEnum.true })).toBe(0);
        expect(Offering.chargeableTotal({ total: 0, usageEntitlement: 10, overageAllowed: overageAllowedEnum.true })).toBe(0);
    });

    test('shows free dimension and overage, drops covered usage', async () => {
        const dimensions = [
            dim({ dimensionId: 'free', consumptionPrice: '0.00' }),
            dim({ dimensionId: 'paid', consumptionPrice: '0.50' }),
            dim({ dimensionId: 'over', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.true }),
            dim({ dimensionId: 'covered', consumptionPrice: '2', usageEntitlement: 100, overageAllowed: overageAllowedEnum.true }),
            dim({ dimensionId: 'nooverage', consumptionPrice: '2', usageEntitlement: 5, overageAllowed: overageAllowedEnum.false }),
            dim({ dimensionId: 'unlimited', consumptionPrice: '2', usageEntitlement: 'inf', overageAllowed: overageAllowedEnum.true }),
            dim({ dimensionId: 'nousage', consumptionPrice: '2' }),
        ];
        const usages = [usage('free', 7), usage('paid', 20), usage('over', 13), usage('covered', 20), usage('nooverage', 20), usage('unlimited', 20)];
        const shown = await run(dimensions, usages, FreeDimensionOnInvoice.show);
        expect(shown).toEqual([
            expect.objectContaining({ name: 'name-free - Plan', quantity: 7, unitCost: 0 }),
            expect.objectContaining({ name: 'name-paid - Plan', quantity: 20, unitCost: 0.5 }),
            expect.objectContaining({ name: 'name-over - Plan', quantity: 3, unitCost: 2 }),
        ]);
        const hidden = await run(dimensions, usages, FreeDimensionOnInvoice.hide);
        expect(hidden).toEqual([
            expect.objectContaining({ name: 'name-paid - Plan', quantity: 20, unitCost: 0.5 }),
            expect.objectContaining({ name: 'name-over - Plan', quantity: 3, unitCost: 2 }),
        ]);
        const noSettings = await run(dimensions, usages, undefined);
        expect(noSettings.length).toBe(3);
    });
});
